package setup

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path"
	"slices"
	"strings"

	"github.com/Marcel-Goehn/kraftwerk/internal/config"
	"github.com/Marcel-Goehn/kraftwerk/internal/prompt"
)

// TodoMarker is on a line a person still has to fill in. `check` refuses
// while one is left.
const TodoMarker = "TODO(kraftwerk)"

// generated opens every file `init` writes.
const generated = "Generated by `kraftwerk init`. Yours to edit: init never overwrites it."

// Harness is what the generated files need to know about the Harness.
type Harness struct {
	Name string
	// Install is the Containerfile snippet that installs it.
	Install string
}

// File is one file `init` creates, by its path below the project root.
type File struct{ Path, Content string }

// Files are every file the answers call for.
func Files(f Facts, a Answers, h Harness) []File {
	in := func(name string) string { return path.Join(config.Dir, name) }
	files := []File{
		gitignoreFile(),
		{in("config.toml"), configTOML(f, a, h)},
	}
	if a.Kind == kindContainer {
		files = append(files, File{in("Containerfile"), containerfile(f, a, h)})
	}
	for _, step := range prompt.Steps {
		files = append(files, File{path.Join(prompt.Dir, step+".md"), prompt.Marker(step) + "\n\n" + prompt.Builtin(step, prompt.Latest(step))})
	}
	return files
}

// gitignoreFile keeps what is personal or a Run's own out of the repo.
func gitignoreFile() File {
	return File{path.Join(config.Dir, ".gitignore"), "# " + generated + "\nconfig.local.toml\n.env\nlogs/\nstate/\n"}
}

// Recreated are the team's files a re-run may bring back, all but the
// config itself and the prompts: a deleted prompt stays deleted. kind is the
// Sandbox kind this person runs. The Containerfile is read from the repo as
// it is now, every language the repo shows being taken as chosen.
func Recreated(f Facts, kind string, h Harness) []File {
	files := []File{gitignoreFile()}
	if kind == kindContainer {
		files = append(files, File{path.Join(config.Dir, "Containerfile"), containerfile(f, Answers{Languages: f.Languages()}, h)})
	}
	return files
}

// Write creates the files below root. What already exists stays as it is.
func Write(root string, files []File) (written, kept []string, err error) {
	opened, err := os.OpenRoot(root)
	if err != nil {
		return nil, nil, err
	}
	defer func() { _ = opened.Close() }()
	for _, file := range files {
		if err := opened.MkdirAll(path.Dir(file.Path), 0o750); err != nil {
			return written, kept, err
		}
		out, err := opened.OpenFile(file.Path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644) //nolint:gosec // these are committed text files
		if errors.Is(err, fs.ErrExist) {
			kept = append(kept, file.Path)
			continue
		}
		if err != nil {
			return written, kept, err
		}
		_, werr := out.WriteString(file.Content)
		if err := errors.Join(werr, out.Close()); err != nil {
			return written, kept, fmt.Errorf("%s: %w", file.Path, err)
		}
		written = append(written, file.Path)
	}
	return written, kept, nil
}

// quote renders s as a TOML basic string.
func quote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b.WriteByte('\\')
			b.WriteRune(r)
		case r < 0x20 || r == 0x7f:
			fmt.Fprintf(&b, "\\u%04X", r)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// quoteList renders items as a TOML list of strings.
func quoteList(items []string) string {
	q := make([]string, len(items))
	for i, s := range items {
		q[i] = quote(s)
	}
	return "[" + strings.Join(q, ", ") + "]"
}

// tomlKey renders k as a TOML key.
func tomlKey(k string) string {
	if strings.IndexFunc(k, func(r rune) bool {
		return (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') && (r < '0' || r > '9') && r != '_' && r != '-'
	}) >= 0 {
		return quote(k)
	}
	return k
}

// allowed are the registries the chosen languages need.
func allowed(f Facts, a Answers) []string {
	var hosts []string
	for _, r := range recipes {
		if slices.Contains(a.Languages, r.id) {
			hosts = append(hosts, r.allow...)
		}
	}
	for _, p := range f.packagesOf(a.Languages) {
		hosts = append(hosts, p.Allow...)
	}
	slices.Sort(hosts)
	return slices.Compact(hosts)
}

// installs are the commands that install the chosen languages' Packages.
func installs(f Facts, a Answers) []string {
	var lines []string
	for _, p := range f.packagesOf(a.Languages) {
		lines = append(lines, chain([]inDir{{p.Dir, p.Install}}))
	}
	return lines
}

// configTOML is the team's config, with every default written out.
func configTOML(f Facts, a Answers, h Harness) string {
	var b strings.Builder
	w := func(lines ...string) {
		for _, l := range lines {
			b.WriteString(l + "\n")
		}
	}
	var verify []string
	for _, name := range wellKnownCommands {
		if a.Commands[name] != "" {
			verify = append(verify, name)
		}
	}
	w("# "+generated, "# `kraftwerk check` validates it.", "",
		"# The config format version.", "version = 1", "",
		"# The Harness that carries out every Step.", "harness = "+quote(h.Name),
		"# The model every Step uses, unless [steps.<name>] sets its own (they can also set harness and effort).", `model = "claude-opus-5-5"`,
		"# The reasoning effort every Step uses; unset leaves the Harness's own default.", `# effort = "high"`,
		"# A semver range the Factory's version must match.", `# factory = "1"`,
		"# Say when a newer Kraftwerk is out, at most once a day and never in CI.", "# update_notice = false",
		"# How many Tickets an Iteration works on at once.", "max_parallel = 1",
		"# How many Iterations a Run may have.", "max_iterations = 10",
		"# The Feedback commands the Factory runs itself to check a change.", "verify = "+quoteList(verify))
	if a.Standards != "" {
		w("# The Coding standards file, read only by the review Step.", "standards = "+quote(a.Standards))
	} else {
		w("# The Coding standards file, read only by the review Step.", `# standards = "docs/coding-standards.md"`)
	}
	var protected []string
	if a.ProtectClaude {
		protected = []string{".claude/"}
	}
	w("# Files agents may not change, besides .kraftwerk/, the compose file and the standards file.", "protected_paths = "+quoteList(protected), "",
		"[tracker]",
		"# The Tracker.", "kind = "+quote(a.Tracker),
		"# The repository, as owner/name.", "repo = "+quote(a.Values["tracker.repo"]),
		"# The label that marks a Ticket Ready for agent.", "ready_label = "+quote(a.Values["tracker.ready_label"]),
		"# The label that marks a claimed Spec.", `in_progress_label = "in-progress"`,
		"# The label a Ticket gets when the agent can't do it.", `cannot_do_label = "needs-investigation"`,
		"# Where the Tracker token comes from: config.local.toml only.", `# token = { stored = "github" }`, "",
		"[branches]",
		"# The remote branch Spec branches are cut from.", "base_branch = "+quote(a.Values["branches.base_branch"]),
		"# The prefix of every branch the Factory creates.", `prefix = "kraftwerk"`, "",
		"[sandbox]",
		"# container or native. \"none\" is only accepted from config.local.toml.", "kind = "+quote(a.Kind),
		"# Extra container engine flags.", "run_args = []",
		"# Extra paths a native Sandbox may read.", "read_only_paths = []",
		"# Extra paths a native Sandbox may write.", "writable_paths = []",
		"# Keep credentials out of the env of the agent's own commands.", "scrub_credentials = true", "",
		"[sandbox.network]",
		"# Hosts the agent may reach. The Harness's own endpoints are added automatically.", "allow = "+quoteList(allowed(f, a)), "",
		"# Environment variables set in every Sandbox. Not for secrets.", "[sandbox.env]", "",
		"# Project secrets, by variable name, each naming where it comes from.", "[sandbox.secrets]", "",
		"[network]",
		"# PEM files trusted in every Sandbox on top of the system roots.", "ca_certs = []",
		"# The proxy the egress proxy chains to, instead of the host's HTTPS_PROXY.", `# upstream_proxy = "http://proxy.example.com:8080"`, "")
	writeServices(w, a)
	w("# Feedback commands: how the agent checks that its change works.", "[commands]")
	if len(verify) == 0 {
		w(`# test = "your test command"`)
	}
	for _, name := range verify {
		w(name + " = " + quote(a.Commands[name]))
	}
	w("")
	writeHook(w, installs(f, a))
	for _, s := range prompt.Steps {
		w("[steps." + s + "]")
		if s == "review" {
			w("# Whether every Ticket gets a fresh review.", "enabled = true")
		}
		w("# Stop the Step after this long without output.", `idle_timeout = "10m"`,
			"# Stop the Step after this long.", `timeout = "60m"`, "")
	}
	w("[logs]", "# How many days Run logs are kept: a positive whole number, or \"forever\".", "keep_days = 30", "",
		"# How you sign in to the Harness: config.local.toml only.", "# [harnesses.claude_code]", `# method = "oauth_token"`, `# secret = { env = "CLAUDE_CODE_OAUTH_TOKEN" }  # a subscription token is never stored`)
	return b.String()
}

// writeServices writes [services], one table per Service.
func writeServices(w func(...string), a Answers) {
	if a.ComposeFile == "" {
		w("# Services the agent can reach, from a compose file.", "# [services]", `# compose_file = "compose.yaml"`, "")
		return
	}
	w("[services]", "# The compose file Services come from.", "compose_file = "+quote(a.ComposeFile), "")
	for _, s := range a.Services {
		w("[services."+tomlKey(s.Name)+"]", "shared = false  # true: one copy serves the whole Run instead of one per Sandbox")
		for _, o := range s.Offers {
			w("# env = { " + tomlKey(o.Name) + " = " + quote(o.Template) + " }")
		}
		w("")
	}
}

// writeHook writes the sandbox_created Hook that runs lines.
func writeHook(w func(...string), lines []string) {
	if len(lines) == 0 {
		w("# Runs in every fresh Sandbox before the agent starts.", "# [[hooks.sandbox_created]]", `# run = "install your dependencies"`, "")
		return
	}
	w("# Installs dependencies from the lockfile in every fresh Sandbox.", "[[hooks.sandbox_created]]")
	if len(lines) == 1 {
		w("# The command.", "run = "+quote(lines[0]))
	} else {
		w("# These run at once; on the first failure the others are stopped.", "parallel = "+quoteList(lines))
	}
	w("# Where it runs.", `where = "sandbox"`, "# Stop it after this long.", `timeout = "5m"`, "")
}

// versionOf is the language's pinned version and where that comes from.
func versionOf(f Facts, r recipe) (version, from string) {
	for _, p := range f.Packages {
		if p.Language == r.id && p.Version != "" {
			return p.Version, p.VersionFrom
		}
	}
	return r.defaultVersion, ""
}

// containerfile is the image every container Sandbox starts from.
func containerfile(f Facts, a Answers, h Harness) string {
	var b strings.Builder
	w := func(lines ...string) {
		for _, l := range lines {
			b.WriteString(l + "\n")
		}
	}
	w("# "+generated,
		"# The image every container Sandbox starts from. Everything your Feedback commands",
		"# need must be installed here. It is rebuilt when this file changes.", "",
		"FROM docker.io/library/debian:bookworm-slim", "",
		"# The tools every agent needs.",
		"RUN apt-get update \\",
		"    && apt-get install -y --no-install-recommends git ca-certificates curl ripgrep \\",
		"    && rm -rf /var/lib/apt/lists/*", "",
		"# Trust the corporate root in `[network] ca_certs`, if there is one.",
		`RUN --mount=type=secret,id=kraftwerk-ca sh -c 'if [ -s /run/secrets/kraftwerk-ca ]; then cp /run/secrets/kraftwerk-ca /usr/local/share/ca-certificates/kraftwerk-ca.crt && update-ca-certificates; fi'`, "")
	for _, r := range recipes {
		if slices.Contains(a.Languages, r.id) {
			w(languageBlock(f, a, r)...)
			w("")
		}
	}
	if len(f.Unknown) > 0 || len(a.Languages) == 0 {
		saw := "The Factory didn't recognise your project's language."
		if len(f.Unknown) > 0 {
			saw = "The Factory saw " + strings.Join(f.Unknown, ", ") + " but has no recipe for it."
		}
		w("# "+TodoMarker+": install your project's language and tools here, then delete this line.",
			"#   "+saw,
			"#   Example: RUN apt-get update && apt-get install -y --no-install-recommends ruby-full", "")
	}
	w("# The system packages: anything else your Feedback commands need (libraries, browsers, CLIs).",
		"# `kraftwerk check --commands` tells you when something is missing.",
		"# RUN apt-get update && apt-get install -y --no-install-recommends <package>", "",
		"# The agent runs as an unprivileged user.",
		"RUN useradd --create-home --uid 1000 agent",
		"USER agent", "",
		"# The Harness. Keep this last: `kraftwerk check` verifies that it runs.")
	b.WriteString(h.Install)
	return b.String()
}

// systemRoots is the CA list, put in front of commands that don't read the
// system's roots by themselves so that they trust a corporate root during
// the build.
const systemRoots = "/etc/ssl/certs/ca-certificates.crt"

// languageBlock are the Containerfile lines that install a language.
func languageBlock(f Facts, a Answers, r recipe) []string {
	version, from := versionOf(f, r)
	title := "# " + r.label + " " + version
	if from != "" {
		title += " (from " + from + ")"
	}
	switch r.id {
	case node:
		block := []string{title, "COPY --from=docker.io/library/node:" + version + "-bookworm-slim /usr/local /usr/local"}
		return append(block, nodeManagers(f, a)...)
	case golang:
		return []string{title, "COPY --from=docker.io/library/golang:" + version + "-bookworm /usr/local/go /usr/local/go", `ENV PATH="/usr/local/go/bin:${PATH}"`}
	case python:
		return []string{title, "COPY --from=ghcr.io/astral-sh/uv:latest /uv /uvx /usr/local/bin/", "ENV UV_PYTHON_INSTALL_DIR=/opt/python",
			"RUN UV_SYSTEM_CERTS=true uv python install " + version}
	default:
		return []string{title, `ENV RUSTUP_HOME=/opt/rustup PATH="/opt/cargo/bin:${PATH}"`,
			"RUN curl -fsSL https://sh.rustup.rs | CARGO_HOME=/opt/cargo sh -s -- -y --profile minimal --default-toolchain " + version + " --component clippy"}
	}
}

// nodeManagers install the package managers the Node Packages use.
func nodeManagers(f Facts, a Answers) []string {
	var managers []string
	for _, p := range f.packagesOf(a.Languages) {
		if p.Language == node && p.Manager != "npm" && !slices.Contains(managers, p.Manager) {
			managers = append(managers, p.Manager)
		}
	}
	slices.Sort(managers)
	var lines []string
	var corepack []string
	for _, m := range managers {
		if m == "bun" {
			lines = append(lines, "RUN NODE_EXTRA_CA_CERTS="+systemRoots+" npm install -g bun")
		} else {
			corepack = append(corepack, m)
		}
	}
	if len(corepack) > 0 {
		// Node 25 stopped shipping corepack.
		lines = append(lines, "ENV COREPACK_ENABLE_DOWNLOAD_PROMPT=0",
			"RUN NODE_EXTRA_CA_CERTS="+systemRoots+" npm install -g --force corepack && corepack enable "+strings.Join(corepack, " "))
	}
	return lines
}
